CREATE TABLE `velix_media_references` (`id` text PRIMARY KEY NOT NULL, `project_id` text NOT NULL REFERENCES `video_projects`(`id`) ON DELETE CASCADE, `search_id` text REFERENCES `velix_discovery_searches`(`id`) ON DELETE SET NULL, `url` text NOT NULL, `kind` text NOT NULL, `title` text NOT NULL, `publisher` text NOT NULL, `published_at` text, `retrieved_at` text NOT NULL, `created_at` text NOT NULL DEFAULT (datetime('now')));
